Android Lint's FragmentDetector source (I recall):
public class FragmentDetector extends Detector implements SourceCodeScanner {
    private static final String FRAGMENT = "android.app.Fragment";
    private static final String SUPPORT_FRAGMENT = "android.support.v4.app.Fragment";

    static final Issue ISSUE = Issue.create(
            "ValidFragment", ...
    );

    @Override
    public List<String> applicableSuperClasses() { return Arrays.asList(FRAGMENT, SUPPORT_FRAGMENT); }

    @Override
    public void visitClass(@NonNull JavaContext context, @NonNull UClass declaration) {
        if (declaration.isInterface()) return;
        checkClass(context, declaration);
    }

    private static void checkClass(JavaContext context, UClass cls) {
        if (cls.hasModifierProperty(PsiModifier.ABSTRACT)) return;
        if (!isFragment(context, cls)) return;

        // Inner class must be static
        PsiClass containingClass = cls.getContainingClass();
        if (containingClass != null && !cls.hasModifierProperty(PsiModifier.STATIC)) {
            context.report(ISSUE, cls, context.getNameLocation(cls), "This fragment class should be static ...");
            return;
        }

        // No-arg constructor
        PsiMethod[] constructors = cls.getConstructors();
        if (constructors.length == 0) return; // implicit public no-arg constructor OK
        boolean hasDefault = false;
        boolean hasPublicDefault = false;
        for (PsiMethod constructor : constructors) {
            if (constructor.getParameterList().getParametersCount() == 0) {
                hasDefault = true;
                if (constructor.hasModifierProperty(PsiModifier.PUBLIC) || constructor.hasModifierProperty(PsiModifier.PROTECTED)) {
                    hasPublicDefault = true;
                }
            }
        }
        if (!hasDefault) {
            context.report(..., "Fragments should have a public default constructor...");
        } else if (!hasPublicDefault) {
            context.report(..., "The default constructor for fragments must be public or protected");
        }
    }
}

