```
class FragmentDetector : Detector(), SourceCodeScanner {

    override fun applicableSuperClasses(): List<String> = listOf(
        "android.app.Fragment",
        "android.support.v4.app.Fragment"
    )

    override fun visitClass(context: JavaContext, declaration: UClass) {
        if (declaration.isInterface || declaration.hasModifierProperty(PsiModifier.ABSTRACT)) return
        if (declaration is UAnonymousClass) return

        // Non-static inner class
        val containingClass = declaration.containingClass
        if (containingClass != null && !declaration.hasModifierProperty(PsiModifier.STATIC)) {
            val message = "This fragment class should be static (declarations of inner classes should be static to prevent memory leaks)"
            context.report(ISSUE, declaration, context.getNameLocation(declaration), message)
            return
        }

        val constructors = declaration.constructors
        if (constructors.isEmpty()) {
            // implicit public no-arg constructor
            return
        }

        var hasPublicNoArg = false
        val nonDefaultConstructors = mutableListOf<PsiMethod>()
        for (constructor in constructors) {
            if (constructor.parameterList.parametersCount == 0) {
                if (constructor.hasModifierProperty(PsiModifier.PUBLIC)) {
                    hasPublicNoArg = true
                }
            } else {
                nonDefaultConstructors.add(constructor)
            }
        }

        if (!hasPublicNoArg) {
            val message = "Fragments must have a public no-arg constructor so they can be re-instantiated by the framework"
            context.report(ISSUE, declaration, context.getNameLocation(declaration), message)
            return
        }

        if (nonDefaultConstructors.isNotEmpty()) {
            for (constructor in nonDefaultConstructors) {
                val message = "Avoid non-default constructors in fragments: use a static factory method or setArguments(Bundle) instead"
                val location = context.getLocation(constructor)
                context.report(ISSUE, constructor, location, message)
            }
        }
    }

    companion object {
        @JvmField
        val ISSUE: Issue = Issue.create(
            id = "ValidFragment",
            briefDescription = "Fragment not instantiatable",
            explanation = """
                From the Fragment documentation:
                **Every** fragment must have an empty constructor, so it can be instantiated when restoring its activity's state. It is strongly recommended that subclasses do not have other constructors with parameters, since these constructors will not be called when the fragment is re-instantiated; instead, arguments can be supplied by the caller with `setArguments(Bundle)` and later retrieved by the Fragment with `getArguments()`.

                Note that this is no longer true when you are using `androidx.fragment.app.Fragment`; with the `FragmentFactory` you can supply any arguments you want (as of version androidx version 1.1).
            """.trimIndent(),
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.FATAL,
            implementation = Implementation(
                FragmentDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}
```

