package com.android.tools.lint.checks

import com.android.SdkConstants.ANDROID_APP_FRAGMENT
import com.android.SdkConstants.ANDROIDX_FRAGMENT_APP_FRAGMENT
import com.android.SdkConstants.CLASS_FRAGMENT
import com.android.tools.lint.detector.api.Category
import com.android.tools.lint.detector.api.Detector
import com.android.tools.lint.detector.api.Implementation
import com.android.tools.lint.detector.api.Issue
import com.android.tools.lint.detector.api.JavaContext
import com.android.tools.lint.detector.api.Scope
import com.android.tools.lint.detector.api.Severity
import com.android.tools.lint.detector.api.SourceCodeScanner
import com.intellij.psi.PsiMethod
import com.intellij.psi.PsiModifier
import org.jetbrains.uast.UAnonymousClass
import org.jetbrains.uast.UClass

class FragmentDetector : Detector(), SourceCodeScanner {

    override fun applicableSuperClasses(): List<String> = listOf(
        ANDROID_APP_FRAGMENT,
        ANDROIDX_FRAGMENT_APP_FRAGMENT
    )

    override fun visitClass(context: JavaContext, declaration: UClass) {
        if (declaration.isInterface) return
        if (declaration.hasModifierProperty(PsiModifier.ABSTRACT)) return

        if (declaration is UAnonymousClass) {
            context.report(
                ISSUE,
                declaration,
                context.getNameLocation(declaration),
                "This fragment should provide a default constructor (a public no-arg constructor)"
            )
            return
        }

        if (!declaration.hasModifierProperty(PsiModifier.PUBLIC)) {
            context.report(
                ISSUE,
                declaration,
                context.getNameLocation(declaration),
                "This fragment should provide a default constructor (a public no-arg constructor)"
            )
            return
        }

        val containingClass = declaration.containingClass
        if (containingClass != null && !declaration.hasModifierProperty(PsiModifier.STATIC)) {
            context.report(
                ISSUE,
                declaration,
                context.getNameLocation(declaration),
                "This fragment should provide a default constructor (a public no-arg constructor)"
            )
            return
        }

        val constructors = declaration.constructors
        if (constructors.isEmpty()) {
            return
        }

        var hasDefault = false
        for (constructor in constructors) {
            if (constructor.parameterList.parametersCount == 0 &&
                constructor.hasModifierProperty(PsiModifier.PUBLIC)
            ) {
                hasDefault = true
                break
            }
        }

        if (!hasDefault) {
            context.report(
                ISSUE,
                declaration,
                context.getNameLocation(declaration),
                "This fragment should provide a default constructor (a public no-arg constructor)"
            )
            return
        }

        // Non-default constructors
        if (context.evaluator.extendsClass(declaration, ANDROIDX_FRAGMENT_APP_FRAGMENT, false)) {
            return
        }

        for (constructor in constructors) {
            if (constructor.parameterList.parametersCount != 0) {
                context.report(
                    ISSUE,
                    constructor,
                    context.getLocation(constructor),
                    "This fragment should not have a non-default constructor"
                )
            }
        }
    }

    companion object {
        @JvmField
        val ISSUE: Issue = Issue.create(
            id = "ValidFragment",
            briefDescription = "Fragment not instantiatable",
            explanation = "...",
            category = Category.CORRECTNESS,
            priority = 6,
            severity = Severity.FATAL,
            implementation = Implementation(
                FragmentDetector::class.java,
                Scope.JAVA_FILE_SCOPE
            )
        )
    }
}
```

