    if (cls.isInterface() || cls.hasModifierProperty(PsiModifier.ABSTRACT)) {
        return;
    }

    if (!cls.hasModifierProperty(PsiModifier.PUBLIC)) {
        String message = String.format(
                "Fragment %1$s is not public so it cannot be instantiated",
                cls.getName());
        context.report(ISSUE, cls, context.getNameLocation(cls), message);
        return;
    }

    if (cls.getContainingClass() != null && !cls.hasModifierProperty(PsiModifier.STATIC)) {
        String message = String.format(
                "Fragment %1$s must be a public static class to be properly recreated from instance state",
                cls.getName());
        context.report(ISSUE, cls, context.getNameLocation(cls), message);
        return;
    }

    PsiMethod[] constructors = cls.getConstructors();
    if (constructors.length > 0) {
        boolean hasDefaultConstructor = false;
        for (PsiMethod constructor : constructors) {
            if (constructor.getParameterList().getParametersCount() == 0) {
                if (constructor.hasModifierProperty(PsiModifier.PUBLIC)) {
                    hasDefaultConstructor = true;
                }
